html+=section('press','06 / Press archive','06 / Archivo de prensa','<p>'+bi('Selected profiles, interviews and project coverage. Dates reflect publisher records.','Perfiles, entrevistas y cobertura de proyectos seleccionados. Las fechas corresponden a los registros de cada medio.')+'</p>'+''.join(f'<a class="press" href="{u}"><b>{n}</b><span>{bi(en,es)} ↗</span></a>' for n,en,es,u in links))
